/* qrcode.min.js — tiny self-contained QR encoder (byte mode, ECC level M,
   versions 1–10, fixed mask 0). Public-domain-style minimal implementation,
   enough for short link codes. Exposes QR.toCanvas(canvas, text, pixelSize).
   No external dependencies (the page CSP forbids CDNs). */

const EXP = new Uint8Array(512), LOG = new Uint8Array(256);
(function () {
  let x = 1;
  for (let i = 0; i < 255; i++) { EXP[i] = x; LOG[x] = i; x <<= 1; if (x & 0x100) x ^= 0x11d; }
  for (let i = 255; i < 512; i++) EXP[i] = EXP[i - 255];
})();
const mul = (a, b) => (a === 0 || b === 0 ? 0 : EXP[LOG[a] + LOG[b]]);

function genPoly(n) {
  let poly = [1];
  for (let i = 0; i < n; i++) {
    const next = new Array(poly.length + 1).fill(0);
    for (let j = 0; j < poly.length; j++) {
      next[j] ^= poly[j];
      next[j + 1] ^= mul(poly[j], EXP[i]);
    }
    poly = next;
  }
  return poly;
}
function rsEC(data, ecLen) {
  const gen = genPoly(ecLen);
  const ec = new Array(ecLen).fill(0);
  for (const d of data) {
    const factor = d ^ ec[0];
    ec.shift(); ec.push(0);
    if (factor !== 0) for (let j = 0; j < ecLen; j++) ec[j] ^= mul(gen[j + 1], factor);
  }
  return ec;
}

// ECC level M block structure: [ecPerBlock, [ [count, dataCw], ... ] ]
const BLOCKS_M = {
  1: [10, [[1, 16]]],
  2: [16, [[1, 28]]],
  3: [26, [[1, 44]]],
  4: [18, [[2, 32]]],
  5: [24, [[2, 43]]],
  6: [16, [[4, 27]]],
  7: [18, [[4, 31]]],
  8: [22, [[2, 38], [2, 39]]],
  9: [22, [[3, 36], [2, 37]]],
  10: [26, [[4, 43], [1, 44]]],
};
const ALIGN = {
  1: [], 2: [6, 18], 3: [6, 22], 4: [6, 26], 5: [6, 30],
  6: [6, 34], 7: [6, 22, 38], 8: [6, 24, 42], 9: [6, 26, 46], 10: [6, 28, 50],
};

function totalDataCw(v) {
  return BLOCKS_M[v][1].reduce((s, [c, d]) => s + c * d, 0);
}
function ccBits(v) { return v < 10 ? 8 : 16; }

function encode(text) {
  const bytes = new TextEncoder().encode(text);
  let version = 0;
  for (let v = 1; v <= 10; v++) {
    const need = Math.ceil((4 + ccBits(v) + 8 * bytes.length) / 8);
    if (need <= totalDataCw(v)) { version = v; break; }
  }
  if (!version) throw new Error('QR: Inhalt zu lang');

  // ---- bit stream ----
  const bits = [];
  const put = (val, len) => { for (let i = len - 1; i >= 0; i--) bits.push((val >> i) & 1); };
  put(0b0100, 4);                 // byte mode
  put(bytes.length, ccBits(version));
  for (const b of bytes) put(b, 8);
  const cap = totalDataCw(version) * 8;
  for (let i = 0; i < 4 && bits.length < cap; i++) bits.push(0); // terminator
  while (bits.length % 8) bits.push(0);
  const padBytes = [0xec, 0x11];
  for (let i = 0; bits.length < cap; i++) put(padBytes[i % 2], 8);

  // ---- codewords + EC, interleaved ----
  const data = [];
  for (let i = 0; i < bits.length; i += 8) {
    let b = 0; for (let j = 0; j < 8; j++) b = (b << 1) | bits[i + j];
    data.push(b);
  }
  const [ecLen, groups] = BLOCKS_M[version];
  const dataBlocks = [], ecBlocks = [];
  let pos = 0;
  for (const [count, dcw] of groups) {
    for (let c = 0; c < count; c++) {
      const blk = data.slice(pos, pos + dcw); pos += dcw;
      dataBlocks.push(blk);
      ecBlocks.push(rsEC(blk, ecLen));
    }
  }
  const out = [];
  const maxData = Math.max(...dataBlocks.map((b) => b.length));
  for (let i = 0; i < maxData; i++)
    for (const blk of dataBlocks) if (i < blk.length) out.push(blk[i]);
  for (let i = 0; i < ecLen; i++)
    for (const blk of ecBlocks) out.push(blk[i]);

  return { version, codewords: out };
}

// ---- matrix construction --------------------------------------------------
function buildMatrix(version, codewords) {
  const size = 17 + 4 * version;
  const m = Array.from({ length: size }, () => new Array(size).fill(null));
  const fn = Array.from({ length: size }, () => new Array(size).fill(false));
  const set = (r, c, v) => { m[r][c] = v ? 1 : 0; fn[r][c] = true; };

  const finder = (r, c) => {
    for (let dr = -1; dr <= 7; dr++) for (let dc = -1; dc <= 7; dc++) {
      const rr = r + dr, cc = c + dc;
      if (rr < 0 || cc < 0 || rr >= size || cc >= size) continue;
      const inRing = dr >= 0 && dr <= 6 && dc >= 0 && dc <= 6;
      const dark = inRing && (dr === 0 || dr === 6 || dc === 0 || dc === 6 ||
        (dr >= 2 && dr <= 4 && dc >= 2 && dc <= 4));
      set(rr, cc, dark ? 1 : 0);
    }
  };
  finder(0, 0); finder(0, size - 7); finder(size - 7, 0);

  // timing
  for (let i = 8; i < size - 8; i++) { set(6, i, i % 2 === 0); set(i, 6, i % 2 === 0); }

  // alignment
  const ap = ALIGN[version];
  for (const r of ap) for (const c of ap) {
    if ((r <= 7 && c <= 7) || (r <= 7 && c >= size - 8) || (r >= size - 8 && c <= 7)) continue;
    for (let dr = -2; dr <= 2; dr++) for (let dc = -2; dc <= 2; dc++)
      set(r + dr, c + dc, Math.max(Math.abs(dr), Math.abs(dc)) !== 1);
  }

  // dark module
  set(size - 8, 8, 1);

  // reserve format areas (filled later)
  for (let i = 0; i < 9; i++) { if (!fn[8][i]) fn[8][i] = true; if (!fn[i][8]) fn[i][8] = true; }
  for (let i = 0; i < 8; i++) { fn[8][size - 1 - i] = true; fn[size - 1 - i][8] = true; }

  // reserve version info (v>=7)
  if (version >= 7) {
    for (let i = 0; i < 6; i++) for (let j = 0; j < 3; j++) {
      fn[i][size - 11 + j] = true; fn[size - 11 + j][i] = true;
    }
  }

  // ---- place data with zig-zag, applying mask 0 ----
  let bitIdx = 0;
  const totalBits = codewords.length * 8;
  const bitAt = (i) => (i < totalBits ? (codewords[i >> 3] >> (7 - (i & 7))) & 1 : 0);
  let upward = true;
  for (let col = size - 1; col > 0; col -= 2) {
    if (col === 6) col = 5; // skip timing column
    for (let i = 0; i < size; i++) {
      const row = upward ? size - 1 - i : i;
      for (let c = 0; c < 2; c++) {
        const cc = col - c;
        if (fn[row][cc]) continue;
        let dark = bitAt(bitIdx++);
        if ((row + cc) % 2 === 0) dark ^= 1; // mask 0
        m[row][cc] = dark;
      }
    }
    upward = !upward;
  }

  // ---- format info (level M=00, mask 0) ----
  const fmt = bch15(0b00000) ^ 0b101010000010010;
  for (let i = 0; i <= 5; i++) m[8][i] = (fmt >> i) & 1;
  m[8][7] = (fmt >> 6) & 1; m[8][8] = (fmt >> 7) & 1; m[7][8] = (fmt >> 8) & 1;
  for (let i = 9; i < 15; i++) m[14 - i][8] = (fmt >> i) & 1;
  for (let i = 0; i < 8; i++) m[size - 1 - i][8] = (fmt >> i) & 1;
  for (let i = 8; i < 15; i++) m[8][size - 15 + i] = (fmt >> i) & 1;

  // ---- version info (v>=7) ----
  if (version >= 7) {
    const vinfo = bch18(version);
    for (let i = 0; i < 18; i++) {
      const bit = (vinfo >> i) & 1;
      const r = Math.floor(i / 3), c = i % 3;
      m[size - 11 + c][r] = bit; m[r][size - 11 + c] = bit;
    }
  }
  return m;
}

function bch15(data) {
  let d = data << 10;
  const g = 0b10100110111;
  for (let i = 14; i >= 10; i--) if ((d >> i) & 1) d ^= g << (i - 10);
  return (data << 10) | d;
}
function bch18(data) {
  let d = data << 12;
  const g = 0b1111100100101;
  for (let i = 17; i >= 12; i--) if ((d >> i) & 1) d ^= g << (i - 12);
  return (data << 12) | d;
}

export const QR = {
  toCanvas(canvas, text, pixelSize = 200) {
    const { version, codewords } = encode(text);
    const m = buildMatrix(version, codewords);
    const n = m.length, quiet = 4, total = n + quiet * 2;
    const scale = Math.max(1, Math.floor(pixelSize / total));
    const dim = scale * total;
    canvas.width = dim; canvas.height = dim;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, dim, dim);
    ctx.fillStyle = '#000';
    for (let r = 0; r < n; r++) for (let c = 0; c < n; c++)
      if (m[r][c]) ctx.fillRect((c + quiet) * scale, (r + quiet) * scale, scale, scale);
  },
};
